
DROP TABLE IF EXISTS eez;
CREATE TABLE eez (
  id SERIAL PRIMARY KEY,
  mrgid_eez INTEGER,
  geoname TEXT NOT NULL,
  pol_type TEXT,
  territory TEXT,
  sovereign TEXT,
  iso_ter TEXT,
  area_km2 DOUBLE PRECISION,
  geom geometry(MultiPolygon, 4326) NOT NULL
);

CREATE INDEX eez_geom_idx ON eez USING GIST (geom);
SELECT count(*) FROM eez;